// lib/services/media_provenance_service.dart
//
// Where a picture in the media library came from: generated by the image
// tool (with its prompt, model and seed), fetched from a URL, or uploaded by
// the user, and in which chat.
//
// None of this is stored with the picture itself. The bucket only knows the
// path, the date and the size. The facts live in the chat that holds the
// picture: the image tool leaves `IMAGE:{"storage_path", "prompt", "model",
// "seed", ...}` as its tool result, and an upload sits in a user message's
// `images` list. So a lookup finds the chats that reference the path (the
// `image_paths` column of `encrypted_chats`, one small query per session),
// reads them cache-first, and keeps the answer on disk next to the cached
// picture, so it is worked out once.
import 'dart:async';
import 'dart:convert';

import 'package:flutter/foundation.dart';

import 'package:chuk_chat/services/chat_storage_service.dart';
import 'package:chuk_chat/services/image_disk_cache.dart';
import 'package:chuk_chat/services/supabase_service.dart';

/// How a picture got into the library.
enum ImageOrigin { generated, fetched, uploaded, unknown }

/// What is known about one picture in the library.
@immutable
class ImageProvenance {
  const ImageProvenance({
    required this.origin,
    this.prompt,
    this.model,
    this.seed,
    this.width,
    this.height,
    this.costEur,
    this.sourceUrl,
    this.chatId,
    this.chatTitle,
    this.createdAt,
  });

  static const ImageProvenance unknown = ImageProvenance(
    origin: ImageOrigin.unknown,
  );

  final ImageOrigin origin;

  /// The text the image model was given.
  final String? prompt;

  /// The generator's display name, e.g. "Krea 2 Large".
  final String? model;
  final String? seed;
  final int? width;
  final int? height;
  final double? costEur;

  /// For a fetched picture: the address it came from.
  final String? sourceUrl;
  final String? chatId;
  final String? chatTitle;

  /// When it was generated or sent, from the chat.
  final DateTime? createdAt;

  bool get isGenerated => origin == ImageOrigin.generated;

  Map<String, dynamic> toJson() => <String, dynamic>{
    'origin': origin.name,
    'prompt': ?prompt,
    'model': ?model,
    'seed': ?seed,
    'width': ?width,
    'height': ?height,
    'costEur': ?costEur,
    'sourceUrl': ?sourceUrl,
    'chatId': ?chatId,
    'chatTitle': ?chatTitle,
    'createdAt': ?createdAt?.toUtc().toIso8601String(),
  };

  static ImageProvenance fromJson(Map<String, dynamic> json) {
    final String originName = json['origin']?.toString() ?? '';
    return ImageProvenance(
      origin: ImageOrigin.values.firstWhere(
        (o) => o.name == originName,
        orElse: () => ImageOrigin.unknown,
      ),
      prompt: _str(json['prompt']),
      model: _str(json['model']),
      seed: _str(json['seed']),
      width: _int(json['width']),
      height: _int(json['height']),
      costEur: _double(json['costEur']),
      sourceUrl: _str(json['sourceUrl']),
      chatId: _str(json['chatId']),
      chatTitle: _str(json['chatTitle']),
      createdAt: DateTime.tryParse(json['createdAt']?.toString() ?? ''),
    );
  }

  ImageProvenance _withChat(String? id, String? title) => ImageProvenance(
    origin: origin,
    prompt: prompt,
    model: model,
    seed: seed,
    width: width,
    height: height,
    costEur: costEur,
    sourceUrl: sourceUrl,
    chatId: chatId ?? id,
    chatTitle: chatTitle ?? title,
    createdAt: createdAt,
  );
}

String? _str(Object? value) {
  if (value == null) return null;
  final String text = value.toString().trim();
  return text.isEmpty ? null : text;
}

int? _int(Object? value) {
  if (value is int) return value;
  if (value is num) return value.toInt();
  return int.tryParse(value?.toString() ?? '');
}

double? _double(Object? value) {
  if (value is num) return value.toDouble();
  return double.tryParse(value?.toString() ?? '');
}

Map<String, dynamic>? _decodeMap(String text) {
  try {
    final Object? decoded = jsonDecode(text);
    return decoded is Map ? Map<String, dynamic>.from(decoded) : null;
  } catch (_) {
    return null;
  }
}

List<Map<String, dynamic>> _decodeList(String? text) {
  if (text == null || text.isEmpty) return const [];
  try {
    final Object? decoded = jsonDecode(text);
    if (decoded is! List) return const [];
    return [
      for (final item in decoded)
        if (item is Map) Map<String, dynamic>.from(item),
    ];
  } catch (_) {
    return const [];
  }
}

/// The tool calls of [message], from its flat list and from its content
/// blocks (newer answers keep their tool calls inside the blocks).
List<Map<String, dynamic>> _toolCallsOf(ChatMessage message) {
  final calls = <Map<String, dynamic>>[..._decodeList(message.toolCalls)];
  for (final block in _decodeList(message.contentBlocks)) {
    final Object? raw = block['toolCalls'];
    if (raw is List) {
      for (final call in raw) {
        if (call is Map) calls.add(Map<String, dynamic>.from(call));
      }
    }
  }
  return calls;
}

/// Works out where [storagePath] came from, using only [messages] of one
/// chat. Null when the chat does not mention the path.
///
/// The image tool's result is the richest source (prompt, model, seed), so
/// it wins over the message's `images` list, which only says that the
/// picture is there.
ImageProvenance? provenanceFromMessages(
  List<ChatMessage> messages,
  String storagePath, {
  String? chatId,
  String? chatTitle,
}) {
  ImageProvenance? fallback;
  for (final ChatMessage message in messages) {
    final DateTime? sentAt = DateTime.tryParse(message.sentAt ?? '');

    for (final Map<String, dynamic> call in _toolCallsOf(message)) {
      final String result = call['result']?.toString() ?? '';
      final bool generated = result.startsWith('IMAGE:');
      final bool fetched = result.startsWith('IMAGE_DATA:');
      if (!generated && !fetched) continue;
      final Map<String, dynamic>? payload = _decodeMap(
        result.substring(generated ? 6 : 11),
      );
      if (payload == null || payload['storage_path'] != storagePath) continue;
      final Map<String, dynamic> args = call['arguments'] is Map
          ? Map<String, dynamic>.from(call['arguments'] as Map)
          : const <String, dynamic>{};
      final DateTime? at =
          DateTime.tryParse(payload['generated_at']?.toString() ?? '') ??
          DateTime.tryParse(call['completedAt']?.toString() ?? '') ??
          sentAt;
      return ImageProvenance(
        origin: generated ? ImageOrigin.generated : ImageOrigin.fetched,
        prompt: generated ? _str(payload['prompt'] ?? args['prompt']) : null,
        model: generated ? _str(payload['model']) : null,
        seed: _str(payload['seed']),
        width: _int(payload['width']),
        height: _int(payload['height']),
        costEur: _double(payload['cost_eur'] ?? payload['costEur']),
        sourceUrl: fetched ? _str(payload['url']) : null,
        chatId: chatId,
        chatTitle: chatTitle,
        createdAt: at,
      );
    }

    if (fallback != null) continue;
    final List<String> images = <String>[];
    try {
      final Object? decoded = jsonDecode(message.images ?? '[]');
      if (decoded is List) images.addAll(decoded.map((e) => e.toString()));
    } catch (_) {}
    final int index = images.indexOf(storagePath);
    if (index < 0) continue;

    if (message.role == 'user') {
      fallback = ImageProvenance(
        origin: ImageOrigin.uploaded,
        chatId: chatId,
        chatTitle: chatTitle,
        createdAt: sentAt,
      );
      continue;
    }
    // An answer's picture without its tool result (older messages): the
    // per-image metadata still says whether it was generated or fetched.
    final List<Map<String, dynamic>> metas = _decodeList(message.imageMetas);
    final Map<String, dynamic> meta = index < metas.length
        ? metas[index]
        : const <String, dynamic>{};
    final bool fetched = meta['source'] == 'fetched';
    fallback = ImageProvenance(
      origin: fetched ? ImageOrigin.fetched : ImageOrigin.generated,
      prompt: fetched ? null : _str(meta['caption']),
      model: _str(meta['model']),
      costEur: _double(message.imageCostEur),
      chatId: chatId,
      chatTitle: chatTitle,
      createdAt: DateTime.tryParse(message.imageGeneratedAt ?? '') ?? sentAt,
    );
  }
  return fallback;
}

class MediaProvenanceService {
  const MediaProvenanceService._();

  static Future<Map<String, List<String>>>? _index;
  static String? _indexUser;
  static final Map<String, Future<ImageProvenance>> _pending = {};
  static final Map<String, Future<StoredChat?>> _chats = {};

  /// Forgets the session's lookups, e.g. after a new picture arrived.
  static void reset() {
    _index = null;
    _indexUser = null;
    _pending.clear();
    _chats.clear();
  }

  /// Where [storagePath] came from. Never throws: without a network or a
  /// matching chat the answer is [ImageProvenance.unknown], which is not
  /// stored on disk, so the next session tries again.
  static Future<ImageProvenance> lookup(String storagePath) {
    return _pending[storagePath] ??= _lookup(storagePath).catchError((_) {
      _pending.remove(storagePath);
      return ImageProvenance.unknown;
    });
  }

  static Future<ImageProvenance> _lookup(String storagePath) async {
    final Map<String, dynamic>? cached = await ImageDiskCache.readMeta(
      storagePath,
    );
    if (cached != null) return ImageProvenance.fromJson(cached);

    final Map<String, List<String>> index = await _chatIndex();
    final List<String> chatIds = index[storagePath] ?? const <String>[];
    ImageProvenance? found;
    for (final String chatId in chatIds) {
      final StoredChat? chat = await (_chats[chatId] ??=
          ChatStorageService.loadFullChat(chatId).catchError((_) => null));
      final List<ChatMessage>? messages = chat?.messagesOrNull;
      if (messages == null) continue;
      final String? title = chat?.customName ?? chat?.title;
      final ImageProvenance? here = provenanceFromMessages(
        messages,
        storagePath,
        chatId: chatId,
        chatTitle: title,
      );
      if (here == null) continue;
      // An upload can be forwarded into later chats; the generating chat is
      // the one that tells the story, so keep looking past a plain upload.
      found ??= here;
      if (here.origin != ImageOrigin.uploaded) {
        found = here._withChat(chatId, title);
        break;
      }
    }
    // Unknown stays in [_pending] for this session (no repeated lookups on
    // every repaint) but is not stored, so the next session tries again.
    if (found == null) return ImageProvenance.unknown;
    unawaited(ImageDiskCache.writeMeta(storagePath, found.toJson()));
    return found;
  }

  /// path -> ids of the chats whose `image_paths` contain it.
  static Future<Map<String, List<String>>> _chatIndex() {
    final String? userId = SupabaseService.auth.currentUser?.id;
    if (userId == null) return Future.value(const <String, List<String>>{});
    if (_indexUser != userId) {
      _index = null;
      _indexUser = userId;
    }
    return _index ??= _loadIndex(userId).catchError((Object _) {
      _index = null;
      return const <String, List<String>>{};
    });
  }

  static Future<Map<String, List<String>>> _loadIndex(String userId) async {
    final rows = await SupabaseService.client
        .from('encrypted_chats')
        .select('id, image_paths')
        .eq('user_id', userId);
    final Map<String, List<String>> index = {};
    for (final row in rows) {
      final String? id = row['id']?.toString();
      final Object? paths = row['image_paths'];
      if (id == null || paths is! List) continue;
      for (final path in paths) {
        (index[path.toString()] ??= <String>[]).add(id);
      }
    }
    return index;
  }
}
